class Solution {
public:
    int numDistinctIslands(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        vector<vector<bool>> visited(m, vector<bool>(n, false));
        set<vector<pair<int, int>>> distinct;
        int dirs[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 1 && !visited[r][c]) {
                    vector<pair<int, int>> shape;
                    vector<pair<int, int>> stk = {{r, c}};
                    visited[r][c] = true;
                    while (!stk.empty()) {
                        auto [cr, cc] = stk.back();
                        stk.pop_back();
                        shape.push_back({cr - r, cc - c});
                        for (auto& dir : dirs) {
                            int nr = cr + dir[0], nc = cc + dir[1];
                            if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] == 1 && !visited[nr][nc]) {
                                visited[nr][nc] = true;
                                stk.push_back({nr, nc});
                            }
                        }
                    }
                    sort(shape.begin(), shape.end());
                    distinct.insert(shape);
                }
            }
        }
        return distinct.size();
    }
};

class Solution {
    public int numDistinctIslands(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        boolean[][] visited = new boolean[m][n];
        Set<String> distinct = new HashSet<>();
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 1 && !visited[r][c]) {
                    List<String> shape = new ArrayList<>();
                    Deque<int[]> stk = new ArrayDeque<>();
                    stk.push(new int[]{r, c});
                    visited[r][c] = true;
                    while (!stk.isEmpty()) {
                        int[] curr = stk.pop();
                        int cr = curr[0], cc = curr[1];
                        shape.add((cr - r) + ":" + (cc - c));
                        for (int[] dir : dirs) {
                            int nr = cr + dir[0], nc = cc + dir[1];
                            if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] == 1 && !visited[nr][nc]) {
                                visited[nr][nc] = true;
                                stk.push(new int[]{nr, nc});
                            }
                        }
                    }
                    Collections.sort(shape);
                    distinct.add(String.join(",", shape));
                }
            }
        }
        return distinct.size();
    }
}

var numDistinctIslands = function(grid) {
    const m = grid.length, n = grid[0].length;
    const visited = Array.from({ length: m }, () => new Array(n).fill(false));
    const distinct = new Set();
    const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];

    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (grid[r][c] === 1 && !visited[r][c]) {
                const shape = [];
                const stk = [[r, c]];
                visited[r][c] = true;
                while (stk.length > 0) {
                    const [cr, cc] = stk.pop();
                    shape.push(`${cr - r}:${cc - c}`);
                    for (const [dr, dc] of dirs) {
                        const nr = cr + dr, nc = cc + dc;
                        if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] === 1 && !visited[nr][nc]) {
                            visited[nr][nc] = true;
                            stk.push([nr, nc]);
                        }
                    }
                }
                shape.sort();
                distinct.add(shape.join(','));
            }
        }
    }
    return distinct.size;
};
